import React, { useState } from 'react'

function Search() {
    const [query, setQuery] = useState('');
    const [sort, setSort] = useState('');
    const [sort_dir, setSort_dir] = useState('');
    const [results, setResults] = useState(null);
    const [loading, setLoading] = useState(false);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [currentItemIndex, setCurrentItemIndex] = useState(0);

    const handleSearch = async () => {
        setLoading(true);
        setResults(null); // Clear previous results
        try {
          const response = await fetch(`http://127.0.0.1:8000/zalora/data?query=${query}&sort=${sort}&sort_dir=${sort_dir}`);
          const data = await response.json();
          setResults(data.items); // Set results after fetching
        } catch (error) {
          console.error('Search failed:', error);
        } finally {
          setLoading(false);
        }
      };

    const nextImage = () => {
        if (results && results[currentItemIndex]?.ImageList?.length > 0) {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % results[currentItemIndex].ImageList.length); // Cycle through the images of the current product
        }
    };

    // Function to go to the previous image
    const prevImage = () => {
        if (results && results[currentItemIndex]?.ImageList?.length > 0) {
            setCurrentIndex((prevIndex) => (prevIndex - 1 + results[currentItemIndex].ImageList.length) % results[currentItemIndex].ImageList.length); // Cycle backward through the images of the current product
        }
    };


    return (
        <div>
            <input
                type="search"
                placeholder="Search product"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
            />
            <button onClick={handleSearch}>Click to search</button>

            {/* Loading state */}
            {loading && <p>Loading...</p>}

            {/* Display results after data is fetched */}
            {results && results.length > 0 && (
                <div>
                    <ul className="carousel">
                        {/* Show the current product */}
                        <li>
                            {/* Check if the current product has an ImageList */}
                            {results[currentItemIndex]?.ImageList?.length > 0 ? (
                                <>
                                    {/* Display the current image based on `currentIndex` */}
                                    <a className="productdetails" href={`https://www.zalora.sg/${results[currentItemIndex].ProductUrl}`} target="_blank" rel="noopener noreferrer">
                                        <img
                                            src={results[currentItemIndex].ImageList[currentIndex]}
                                            alt={results[currentItemIndex].Name}
                                        />
                                        <label className="itemname">{results[currentItemIndex].Name}</label>
                                        <span className="price">{results[currentItemIndex].Price}</span>
                                        <span className="brand">{results[currentItemIndex].Brand}</span>
                                        <span className="seller">Zalora</span>
                                        <span className="avg_rating">{results[currentItemIndex].ReviewStatistics.AvgRating}</span>
                                    </a>
                                </>
                            ) : (
                                <p>No images available for this product</p>
                            )}
                        </li>
                    </ul>

                    {/* Navigation buttons for images */}
                    <button onClick={prevImage}>Previous Image</button>
                    <button onClick={nextImage}>Next Image</button>

                    {/* Product navigation */}
                    <div>
                        {results.map((item, index) => (
                            <button key={index} onClick={() => selectItem(index)}>
                                {item.Name}
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

export default Search;
